// from https://github.com/nickcom/phpsqlplus
class MysqlPlus {
    private $mysqli;
    private $columns; // columns associated with this query

    function __construct($host = 'localhost', $db = 'db',
                    $username = 'root', $password = '') {
        if ($this->connect()) { 
            throw new Exception("MySQL connection failed");
        }
    }

    function connect() {
        try {
            $conn = mysqli_connect($host, $username, $password, $db);
            if (!$conn) throw new Exception(mysqli_error());
            return $conn;
        } catch (\Exception $ex) {
            return false;
        }
    }

    public function get_columns($table) {
        // Example usage: table name must be passed as string
        $result = $this->query('SHOW COLUMNS FROM ' . $table);
        while ($row = $result->fetch_assoc()) {
            $this->columns[] = $row['Field'];
        }
        return $this->columns;
    }

    public function query($sql) {
        if (!empty($sql)) {
            $q = $this->mysqli->prepare($sql);
            $q->execute();
            $q->store_result();
            $q->bind_result($res);
            $q->fetch();
            return $res;
        }
    }
}

