String evaluateCallJson(String type) {

    Logs.verbose("Evaluate call json with url=");
    String result = null;

    try {
        final URL url = new URL(type);
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        result = sb.toString();
        reader.close();
    } catch (IOException e) {
        Logs.error(e.getMessage());
    }

    return result;
}
